export function pick(language) {
    return languages.includes(language) ? language : "en";
}

export function t(language, key, vars = {}) {
    const text = messages[pick(language)][key] ?? en[key] ?? vars.message ?? key;
    return text.replace(/\{(\w+)\}/g, (match, name) => vars[name] ?? match);
}

export function phaseText(phase, field, language) {
    return phase?.i18n?.[pick(language)]?.[field] ?? phase?.[field];
}
